INSERT INTO public.liqueurs (id, title, ingredients, yield_ml, method, description, validity, image_url) VALUES
(2, 'Licor de Café', '[{"name":"Bebida Base","amount":"500","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Café em grão","amount":"150","unit":"g","note":"Ou café moído"},{"name":"Casca de Canela","amount":"1","unit":"unidade","note":""},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":"Colher de sopa"},{"name":"Água","amount":"250","unit":"ml","note":""},{"name":"Açúcar","amount":"500","unit":"g","note":""}]', '550', '["O café moído em grão: em um recipiente devido, coloque o café a canela em pau, a baunilha e a bebida base. Misture tudo e feche o recipiente, embale em papel alumínio, pano ou papel para que fique protegido contra a luz, manter em descanso, agitando de vez em quando pelos próximos 10 dias. Após os 10 dias, filtre, pode ser um filtro de papel e uma peneira.","CALDA: Prepare a calda perolada base. Igual e o mesmo volume de café com a calda perolada, misture os dois volumes, mexa e engarrafar."]', NULL, '3 a 5 anos', NULL),
(3, 'Licor de Abacaxi', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal."},{"name":"Abacaxi","amount":"2","unit":"unidades","note":"Médios e maduros"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1000', '["Picar o abacaxi em cubos sem o nó, leve uma panela ao fogo com água e deixe ferver até amolecer, coloque o açúcar e mexa com uma colher até engrossar e deixe esfriar.","Em um recipiente higienizado, coloque a bebida base e misture, deixe macerando por 40 dias.","Com a ajuda de uma peneira, pano de algodão ou filtro de papel, filtre a infusão e engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(4, 'Licor de Açaí', '[{"name":"Bebida Base","amount":"600","unit":"ml","note":"Cachaça, vodka ou álcool cereal"},{"name":"Polpa de Açaí","amount":"400","unit":"g","note":""},{"name":"Água","amount":"600","unit":"ml","note":""},{"name":"Açúcar","amount":"600","unit":"g","note":""}]', '1000', '["Em um recipiente limpo, coloque a polpa descongelada, se for o fruto, lave bem, adicione a bebida de sua preferência, feche e envolva em papel alumínio ou plástico, deixe curtir por 20 dias, agite sempre que puder.","CALDA: Leve um panela ao fogo médio, com água e o açúcar, mexa sempre até fazer um fio fino e perolado, deixe amornar, adicione ao licor e deixe curtir por mais 20 dias. ","Após coe e filtre com pano de algodão."]', NULL, '3 a 5 anos', NULL),
(5, 'Licor de Amora', '[{"name":"Bebida Base","amount":"750","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Amoras","amount":"500","unit":"g","note":"Silvestres comum"},{"name":"Água","amount":"1","unit":"l","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""}]', '500', '["Em um recipiente higienizado, coloque a amora e a bebida de sua preferência, feche e envolva em papel alumínio e deixe curtir por 30 dias, agite sempre que possível.","Após 30 dias, use uma peneira com algodão ou pano de algodão para filtrar.","CALDA: Leve uma panela ao fogo médio e adicione a água e o açúcar, mexa até obter uma calda fina e perolada, tire do fogo e deixe amorna. Misture ao licor muito bem, feche o recipiente e deixe por mais 10 dias macerando, após isso engarrafe."]', NULL, '3 a 5 anos', NULL),
(6, 'Licor de Ameixa', '[{"name":"Bebida Base","amount":"750","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Ameixa Vermelha","amount":"500","unit":"g","note":""},{"name":"Essência de Baunilha","amount":"2","unit":"colheres","note":"Ou uma Fava de baunilha"},{"name":"Açúcar","amount":"750","unit":"g","note":""},{"name":"Água","amount":"1,5","unit":"l","note":""}]', '1000', '["Em um recipiente higienizado, coloque a fruta já cortada, coloque a bebida de sua preferência, adicione a baunilha, agite para misturar.","Envolva o recipiente em papel alumínio ou plástico e deixe curtir por 90 dias. Após 90 dias usar uma peneira com pano de algodão, filtre.","CALDA: Leve uma panela ao fogo médio e adicione a água e o açúcar, mexa até obter uma calda fina e perolada, tire do fogo e deixe amorna. Misture ao licor muito bem, após isso engarrafe."]', NULL, '3 a 5 anos', NULL),
(7, 'Licor de Acerola', '[{"name":"Bebida base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Acerola","amount":"1","unit":"kg","note":"Frutos maduros"},{"name":"Açúar","amount":"800","unit":"g","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["Em um recipientes higienizado, lave as frutas em água corrente. Leve a uma panela ao fogo médio e coloque o açúcar e deixe levantar fervura por 5 minutos, aí coloque a acerola e deixe ferver por mais 15 minutos mexendo sempre.","Deixe esfriar completamente e vamos coar com ajuda de uma peneira de pano de algodão ou filtro de papel a infusão e engarrafe e etiquete. Após a filtragem, adicione a bebida base e misture, envolva em papel alumínio ou plástico e deixe curtir por 10 dias. Agite sempre que puder, após 10 dias, engarrafe."]', NULL, '3 a 5 anos', NULL),
(8, 'Licor de Ameixa Amarela (Nêspera)', '[{"name":"Bebida Base","amount":"500","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Ameixa amarela","amount":"1","unit":"kg","note":""},{"name":"Açúcar","amount":"600","unit":"g","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["Lave as ameixas e coloque no recipiente com a bebida de sua preferência, feche e deixe macerar por 7 dias, agite sempre que puder. ","Após esses dias de maceração, com a ajuda de uma peneira de pano de algodão ou filtro de papel, filtre a infusão e reserve.","CALDA: Leve uma panela ao fogo com água e o açúcar, mexa até levantar fervura por 5 minutos, e obter uma calda perolada e fina, desligue e deixe amornar, adicione ao licor, engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(9, 'Licor de Banana', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Bananas nanicas","amount":"600","unit":"g","note":""},{"name":"Açúcar","amount":"500","unit":"g","note":""},{"name":"Água","amount":"250","unit":"ml","note":""},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":""},{"name":"Corante alimentício","amount":"10","unit":"gotas","note":""}]', '1000', '["Em um pote de vidro, coloque as bananas picadas e adicione a bebida escolhida, adicione a baunilha para dar equilíbrio a bebida, feche o recipiente.","Agite para misturar a essência a maceração será de 15 dias protegido da luz, agite sempre que puder. Prepare o xarope perolado, lembrando que apenas o misture, assim que esfriar.","Filtre em uma peneira para tirar as partes maiores e depois filtre com um coador de papel ou cano, esta ação pode ser simultânea. Misture o xarope e coloque o corante alimentício ou ele em pó, uma colher de chá, misture e engarrafe."]', NULL, '3 a 5 anos', NULL),
(10, 'Licor de Tangerina (Bergamota)', '[{"name":"Bebida Base","amount":"900","unit":"ml","note":"Cachaça, gin, ou rum."},{"name":"Tangerina","amount":"450","unit":"g","note":"Cascas da tangerina."},{"name":"Água","amount":"200","unit":"ml","note":""},{"name":"Açúcar","amount":"400","unit":"g","note":""}]', '1000', '["Em um recipiente limpo, coloque as cascas, retire a parte branca, feche o recipiente e envolva em papel alumínio por 30 dias. Após esse tempo, faça uso de uma peneira com filtro.","CALDA: Leve uma panela ao fogo médio, coloque alguns pedaços da casca da tangerina. Ferva as cascas por 5 minutos. Retire as cascas e coloque o açúcar, misture até perolar, desligue e deixe esfriar, misture o xarope ao licor e mexa bem, engarrafe."]', NULL, '3 a 5 anos', NULL),
(11, 'Licor de Cacau', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka ou álcool cereal."},{"name":"Sementes de Cacau","amount":"500","unit":"g","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"900","unit":"ml","note":""},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":"Colher de chá."}]', '1000', '["Torre o cacau e depois, descasque e moa. Em um recipiente higienizado, coloque o cacau moído, a bebida base e a baunilha.","Leve ao fogo o açúcar e a água, até obter uma calda fina e perolada, deixe amornar, adicione na infusão. Deixe em infusão macerando por 15 dias.","Após primeira maceração com a ajuda de uma peneira pano de algodão ou filtro de papel, filtre a infusão e deixe macerar por mais 30 dias.","Após a segunda maceração filtre novamente de 30 em 30 dias por 6 meses, o cacau dispensa muita gordura. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(12, 'Licor de Caju', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Suco de Caju Concentrado","amount":"500","unit":"ml","note":""},{"name":"Suco de Limão","amount":"50","unit":"ml","note":"Ou 3 colheres de sopa"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":"Colher de chá"}]', '1000', '["Em um recipiente higienizado, coloque a bebida base, o limão, a baunilha, o suco de caju e mexa bem (Obs.: com o fruto, leva-se mais de 6 meses para ficar pronto.) Agite o recipiente e deixe curtir por 10 dias.","CALDA: Leve uma panela ao fogo médio com a água e o açúcar, mexa até levantar fervura (10 minutos) e deixe esfriar, misture ao licor e engarrafe."]', NULL, '3 a 5 anos', NULL),
(13, 'Licor de Cereja', '[{"name":"Bebida Base","amount":"700","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Cereja em Calda","amount":"200","unit":"g","note":""},{"name":"Balas de Cereja","amount":"25","unit":"unidades","note":"Ou 10 halls de cereja"},{"name":"Água","amount":"100","unit":"ml","note":""},{"name":"Açúcar","amount":"200","unit":"g","note":""}]', '700', '["Em um recipiente higienizado coloque acereja com calda, as balas de cereja, adicione a bebida base, fechar e deixar curtir por 3 dias, agitando 2 a 3 vezes ao dia.\nApós 3 dias use uma peneira pano de algodão ou filtro de papel, filtre a infusão.","CALDA: Leve uma panela ao fogo médio com a água, adicione uma bala e a derreta, depois adicione o açúcar e mexa até perolar, retire do fogo e deixe esfriar, misture ao licor e mexa bem. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(14, 'Licor de Cereja do Rio Grande', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Cereja em Calda","amount":"800","unit":"g","note":""},{"name":"Água","amount":"800","unit":"ml","note":""},{"name":"Açúcar","amount":"600","unit":"g","note":""}]', '1000', '["Em um recipiente higienizado coloque acereja, adicione a bebida base, fechar e deixe macerar por 30 dias e agitar de 2 a 3 vezes ao dia.\nCom a ajuda de uma peneira pano de algodão ou filtro de papel, filtre a infusão.","CALDA: Leve uma panela ao fogo médio com a água, adicione o açúcar e mexa até obter uma calda fina e perolada, retire do fogo e deixe amornar, misture a infusão e mexa bem. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(15, 'Licor de Coco', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Coco","amount":"250","unit":"g","note":"Ou polpa de um coco"},{"name":"Açúcar","amount":"500","unit":"g","note":"300g para maceração e 200g para a calda"},{"name":"Água","amount":"300","unit":"ml","note":""}]', '1000', '["Em um recipiente higienizado, coloque a polpa do coco, 300 g de açúcar e a bebida base, feche e deixe macerar por 20 dias, agite o máximo de vezes que puder. Após 20 dias coe em uma peneira e novamente em uma peneira ultra fina ou pano.","CALDA: Leve uma panela ao fogo baixo e coloque a água e 200 g de açúcar, mexa\naté obter uma calda fina e perolada, retire e deixe amornar, adicione na infusão e misture até homogeneizar. ** Você também pode comprar a polpa já extraída, lembrando o fruto é melhor."]', NULL, '3 a 5 anos', NULL),
(16, 'Licor de Framboesa', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Framboesa","amount":"1","unit":"kg","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["Lave as frutas em água corrente e coloque em um recipiente higienizado com a bebida base, feche e deixe macerar por 30 dias, envolva em papel-alumínio ou plástico, agite sempre que puder.\nApós 30 dias, com a ajuda de uma peneira de algodão ou pano de algodão, filtre a infusão.","CALDA: Leve uma panela ao fogo com a água e o açúcar, mexa até obter uma calda fina e perolada, na cor caramelado, retire e deixe amornar, adicione ao licor e mexa bem. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(17, 'Licor de Figo', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Figos maduros","amount":"1","unit":"kg","note":"Ou 1 lata de figo sem calda (400g)"},{"name":"Água","amount":"1","unit":"l","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""}]', '1000', '["Em um recipiente higienizado, coloque os frutos já preparados (retirando a haste caso seja in natura, se for em calda apenas os corte em pedaços), coloque a bebida base e feche o recipiente, agite e deixe curtir por 30 dias, agite sempre que puder.\nApós 30 dias, com a ajuda de umapeneira algodão ou pano de algodão,filtre a solução.","CALDA: Leve uma panela ao fogo médio e coloque a água e o açúcar, mexa até obter uma calda fina e perolada, desligue e deixe amornar, misture ao licor.\nObs.: caso feito com frutos em calda adicione metade da calda ao licor e engarrafe e etiquete."]', NULL, '5 anos', NULL),
(18, 'Licor de Goiaba', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Goiaba Madura","amount":"1","unit":"kg","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["Em uma panela em fogo médio coloque a goiaba descascada e triture a fruta, adicione o açúcar e a água, misture, assim que começar a ferver, mexa por 30minutos, após o tempo determinado desligue e deixe esfriar.","Em um recipiente higienizado coloque a bebida base e adicione a calda de goiaba sem peneirar, feche o recipiente e envolva com papel alumínio ou plástico e deixe macera por 10 dias.\nApós os 10 dias filtre a infusão com ajuda de algodão, filtro de papel ou pano.","Obs.: Você pode deixar sem filtra se quiser ele rústico com polpa. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(19, 'Licor de Jabuticaba', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Jabuticaba","amount":"1","unit":"kg","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1000', '["Use um recipiente de vidro higienizado, coloque as jabuticabas, faça um corte em toda as frutas, adicione a bebida base e feche o recipiente, deixe macerar por 10 dia, mas porem abra a tampa todos os dias porque ele cria um gás na sua fermentação.","Após os 10 dias, coe o licor em uma peneira fina ou um pano limpo, esmague as frutas para tirar a poupa, com outra peneira ultra fina coe novamente o licor.","CALDA: Leve uma panela ao fogo baixo com a água, o açúcar, e a casca da jabuticaba coada, mexa até obter uma calda grossa retire e deixe amornar, peneire e misture ao licor mexer e engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(20, 'Licor de Kiwi', '[{"name":"Bebida Base","amount":"500","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Kiwi","amount":"300","unit":"g","note":"Ou 5 frutos"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '500', '["Lave as frutas em água corrente, descasque e corte em pedaços.\nNo recipiente higienizado coloque os pedaços da fruta a bebida base, envolva em papel alumínio e deixe macera por 30 dias, agite sempre que puder.","CALDA: Leve uma panela ao fogo médio e com a água e o açúcar até obter uma calda fina e perolada, retire e deixe amorna. No recipiente misture a calda ao licor e a fruta e envolva novamente em papel alumínio ou plástico e deixe curtir por mais 15 dias.\nApós 15 dias com ajuda de uma peneira com algodão ou pano de algodão filtre e engarrafe."]', NULL, '3 a 5 anos', NULL),
(21, 'Licor de Laranja', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Laranja","amount":"800","unit":"g","note":"Ou 8 a 12 unidades [pera, lima, bahia ou valência]"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["Em um recipiente higienizado coloque a laranja escolhida e a bebida base e deixe macera em local fresco e escuro por 20 dias. Obs.: com casca deixe no claro para não amarga.\nAgite sempre que puder pelo menos uma vez ao dia.","CALDA: Leve uma panela ao fogo baixo com a água e o açúcar mexa até obter uma calda fina e perolada, adicione a infusão e deixe macera por mais 20 dias.\nCom ajuda de uma peneira, pano de algodão filtre a infusão engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(22, 'Licor de Laranja da Terra', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Laranja","amount":"400","unit":"g","note":"Ou 3 laranjas da terra, somente as cascas."},{"name":"Açúcar","amount":"900","unit":"g","note":""},{"name":"Noz Moscada Ralada","amount":"1/2","unit":"unidade","note":""}]', '1000', '["Retire a casca da laranja e em um recipiente higienizado coloque a bebida base e\nas cascas das laranjas mais o açúcar ingredientes e deixar em maceração por 7 dias.","Com ajuda de uma peneira algodão ou pano de algodão filtre engarrafar e etiquetar."]', NULL, '5 anos', NULL),
(23, 'Licor de Limão Taiti', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Água Quente","amount":"500","unit":"ml","note":""},{"name":"Folhas de Hortelã","amount":"10","unit":"folhas","note":"Opcional"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água Fria","amount":"500","unit":"ml","note":""}]', '1000', '["Recipiente Limpo. Lave os limões em água corrente e as folhas de hortelã também. Com um garfo ou palito de dente faça furos no limão.\nColoque os limões e as folhas de hortelã no recipiente 500ml de (água fervida e fria também pode ser mineral) adicione a bebida de sua preferência feche e agite um pouco para misturar os ingredientes.","Deixe para curtir ao sol por 45 dias o máximo de horas possível durante o dia agite sempre que possível.\nApós 45 dias vamos coar o licor.\nCom uma peneira ou coador filtre o líquido.","CALDA: leve uma panela ao fogo baixo e coloque a água e o açúcar mexa até obter uma calda fina e perolado deixe amorna e misture ao licor e engarrafa e etiquete."]', NULL, '3 a 5 anos', NULL),
(24, 'Licor de Limão Siciliano', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Água Fervida","amount":"500","unit":"ml","note":""},{"name":"Hortelã","amount":"10","unit":"folhas","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água Fria","amount":"500","unit":"ml","note":""},{"name":"Limão Siciliano","amount":"200","unit":"g","note":"ou 5 limões"}]', '1000', '["Recipiente Limpo. Lave os limões em água corrente e as folhas de hortelã também. Com um garfo ou palito de dente faça furos no limão. Coloque os limões e as folhas de hortelã no recipiente 500ml de (água fervida e fria também, pode ser mineral) adicione a bebida de sua preferência feche e agite um pouco para misturar os ingredientes.","Deixe para curtir ao sol por 45 dias o máximo de horas possível durante o dia agite sempre que possível. Após 45 dias vamos coar o licor. Com uma peneira ou coador filtre o líquido.","CALDA: leve uma panela ao fogo baixo e coloque a água e o açúcar mexa até obter uma calda fina e perolado deixe amorna e misture ao licor e engarrafa e etiquete."]', NULL, '3 a 5 anos', NULL),
(25, 'Licor de Manga', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Manga","amount":"1","unit":"kg","note":"Ou 3 mangas maduras"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1000', '["Lave as frutas em água corrente, descasque e retire a polpa. Em um recipiente coloque a polpa das mangas e a bebida base tampe e deixe por 1 hora e agite bem.\nCom um pano de algodão retire a infusão do recipiente e deixe fechada e preserve a polpa.","CALDA: Leve uma panela ao fogo baixo coloque a água e o açúcar misture até obter uma calda fina e perolada. Ferva novamente a calda e coloque a polpa da manga por 5 minutos retire deixe amorna e filtre a calda direto na infusão.\nEnvolva o recipiente com papel alumínio ou plástico por 15 dias agite sempre que puder. Após os 15 dias engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(26, 'Licor de Maçã', '[{"name":"Bebida Base","amount":"700","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Maça","amount":"400","unit":"g","note":"Ou 6 maças"},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":"Colher de sopa"},{"name":"Água","amount":"200","unit":"ml","note":""},{"name":"Açúcar","amount":"400","unit":"g","note":""}]', '700', '["Lave a fruta em água corrente depois descasque e corte em pedaços. No recipiente de vidro coloque os pedaços da fruta, adicione a bebida base, a essência de baunilha e feche, agite para misturar e envolva em papel alumínio ou plástico e deixe curtir por 15 dias agitar sempre que puder.\nApós 15 dias com ajuda de uma peneira pano de algodão, filtro de papel, filtre a infusão.","Leve uma panela ao fogo médio com a água e o açúcar, mexer até obter uma calda fina e perolada, retire e deixe amornar, misture na infusão, mexer bem engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(27, 'Licor de Maracujá', '[{"name":"Bebida Base","amount":"300","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Maracujá","amount":"200","unit":"g","note":"Ou 5 maracujás maduros"},{"name":"Açúcar","amount":"250","unit":"g","note":""},{"name":"Água","amount":"125","unit":"ml","note":""}]', '300', '["Com um maracujá maduro corte o topo do maracujá e coloque a bebida para extrair o aroma da fruta.\nMexa por 30 minutos e coe a fruta até ficar apenas os caroços.","CALDA: Para fazer a calda leve uma panela ao fogo baixo e coloque o açúcar e a água misture até ter uma calda consistente ficar em uma cor perolada. Deixe esfriar e misture ao suco do maracujá E em seguida engarrafe."]', NULL, '3 a 5 anos', NULL),
(28, 'Licor de Melancia', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Melancia","amount":"400","unit":"g","note":"Ou 8 pedaços robustos"},{"name":"Cravo da ìndia","amount":"4","unit":"unidades","note":""},{"name":"Canela em Pau","amount":"2","unit":"unidades","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1000', '["No recipiente coloque a polpa da melancia adicione a bebida base e deixe macera por 15 dias, envolva o recipiente em alumínio ou plástico, agite sempre que puder.\nApós 15 dias com ajuda de uma peneira algodão ou pano de algodão filtre a infusão.","CALDA: Leve uma panela ao fogo médio com água e o açúcar mexer até obter uma calda grossa caramelizada e misture a infusão, coloque o cravo e a canela no recipiente e deixe macera por mais 60 dias filtre novamente engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(29, 'Licor de Melão', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Melão","amount":"900","unit":"g","note":"Ou 1 melão de qualquer tipo maduro"},{"name":"Hortelã","amount":"10","unit":"folhas","note":""},{"name":"Açúcar","amount":"600","unit":"g","note":""},{"name":"Água","amount":"300","unit":"ml","note":""}]', '1000', '["Lave a fruta em água corrente e retire a polpa e corte em cubos, coloque no recipiente com a bebida base, a hortelã e envolva o recipiente com papel alumínio ou plástico e deixe curtir por 20 dias agite sempre que puder.\nApós 20 dias, com a ajuda de uma peneira algodão ou pano de algodão filtre a solução.","CALDA: Leve uma panela ao fogo médio e coloque a água, o açúcar e mexa até obter uma calda fina e perolada, adicione a infusão e mexa até homogeneizar. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(30, 'Licor de Mirtilo', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Mirtilo","amount":"500","unit":"g","note":""},{"name":"Açúcar","amount":"750","unit":"g","note":""}]', '1000', '["Lave a fruta em água corrente corte a fruta e coloque no recipiente, junte o açúcar, a bebida base, feche o recipiente, agite e envolva em papel alumínio ou plástico, deixe macerar por 45 dias, agite sempre que puder.","Após os 45 dias, com a ajuda de uma peneira algodão ou pano de algodão filtre a solução, retorne ao recipiente e deixe macera por mais 30 dias. Passado o tempo, engarrafe."]', NULL, '3 a 5 anos', NULL),
(31, 'Licor de Morango', '[{"name":"Bebida Base","amount":"900","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Morango","amount":"150","unit":"g","note":"Ou 20 morangos graúdos"},{"name":"Canela em Pau","amount":"2","unit":"unidades","note":""},{"name":"Água","amount":"150","unit":"ml","note":""},{"name":"Açúcar","amount":"300","unit":"g","note":""}]', '1000', '["Lave as frutas em água corrente e faça dois cortes na fruta, coloque-as no recipiente junto com a canela em pau, acrescente a bebida base e feche o vidro, e deixe curti por 30 dias, agite sempre que puder.\nApós 30 dias, com a ajuda de uma peneira de trama fina esprema a fruta para tirar o suco depois peneire em um pano de algodão ou filtro de papel..","CALDA: Leve uma panela ao fogo baixo com a água e o açúcar, mexer até obter uma calda fina e perolada, retirar do fogo e deixar amorna, adicionar a infusão. Engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(32, 'Licor de Pêssego', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Pêssego","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"300","unit":"ml","note":""},{"name":"Açúcar","amount":"800","unit":"g","note":""}]', '1000', '["Lave as frutas em água corrente descasque e retire os caroços..\nNo recipiente coloque os pêssegos já cortados adicione a bebida base, envolva o recipiente em papel alumínio ou plástico deixe macerar por 15 dias, agite sempre que puder.","Após 15 dias com a ajuda de uma peneira algodão ou pano de algodão filtre.\nNão precisa fazer calda, adicione o açúcar e a água diretamente ao licor, fechar e deixar por mais 10 dias para macerar, agitar todos os dias. Após isso engarrafar."]', NULL, '5 anos', NULL),
(33, 'Licor de Pitaia', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Pitaia Vermelha Madura","amount":"250","unit":"g","note":"Ou 3 pitaias maduras"},{"name":"Açúcar","amount":"750","unit":"g","note":""},{"name":"Água","amount":"750","unit":"ml","note":""},{"name":"Cravo da ìndia","amount":"20","unit":"unidades","note":""},{"name":"Anis Estrelado","amount":"10","unit":"unidades","note":""}]', '1000', '["Lave o fruto em água corrente retire as partes verdes do fruto, corte o fruto em pedaços retirando a polpa, vamos usar apenas a parte da casca.","Leve uma panela ao fogo médio com água e ferva, mexa e adicione os cravos, o anis (opcional), mantenha na fervura por 10 minutos adicione o açúcar e ferva por mais 10 minutos, desligue e deixe amornar.","Com a ajuda de uma peneira com algodão ou pano de algodão e filtre.\nNo recipiente adicione a bebida base e mexa bem, engarrafe e etiquete."]', NULL, '5 anos', NULL),
(34, 'Licor de Rapadura', '[{"name":"Bebida Base","amount":"2","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Rapadura","amount":"800","unit":"g","note":""},{"name":"Água","amount":"500","unit":"ml","note":"Para suavizar o teor alcoólico (opcional)"},{"name":"Canela em casca","amount":"2","unit":"unidades","note":"opcional"},{"name":"Cravo da ìndia","amount":"20","unit":"unidades","note":"opcional"},{"name":"Casca de Laranja","amount":"5 ","unit":"cascas","note":"opcional"},{"name":"Laranja ou Laranjeira","amount":"10","unit":"folhas","note":"opcional"}]', '2000', '["No recipiente higienizado coloque a rapadura em pedaços, adicione a bebida base, feche o recipiente e deixe macerar por 10 dias, agite sempre que puder, se for saborizar adicione junto a maceração.","Após os 10 dias, coloque os 500 ml de água para suavizar o teor alcoólico é opcional. Obs.: Se tiver os demais ingrediente lembrar de coar com ajuda de uma peneira. E engarrafar."]', NULL, '5 anos', NULL),
(35, 'Licor de Romã', '[{"name":"Bebida Base","amount":"1,5","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Romã","amount":"250","unit":"g","note":"ou 5 frutos de romã"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1500', '["Lave a fruta em água corrente retire os gomos e coloque em um recipiente higienizado, adicione 600 g de açúcar e feche o recipiente, agite e deixe macerar por 15 dias, agite sempre que puder.","Após 15 dias, adicione a bebida base e feche, deixe curtir por 60 dias, agite sempre que puder.\nApós 60 dias com a ajuda de uma peneira algodão ou pano de algodão filtre a infusão.","CALDA: Leve uma panela ao fogo e coloque a água e 400 g de açúcar, mexa até obter uma calda fina perolada, desligue e deixe macera misture ao licor mexa bem e engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(36, 'Licor de Uva', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Uva","amount":"1","unit":"kg","note":""},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"1","unit":"l","note":""}]', '1000', '["No recipiente higienizado, coloque as uvas com um corte, adicione a bebida base e envolva em papel alumínio ou plástico, deixe curtir por 45 dias, agite sempre que puder.\nApós 45 dias, com uma peneira e um filtro feito com algodão ou pano de algodão, filtre a infusão.","CALDA: Leve uma panela ao fogo médio coloque a água e o açúcar, mexa até obter uma calda fina e perolada, desligue, deixe amornar e adicione a infusão, misture bem e engarrafe e etiquete."]', NULL, '3 a 5 anos', NULL),
(37, 'Licor de Damasco', '[{"name":"Vinho branco Suave","amount":"1","unit":"l","note":""},{"name":"Álcool de Cereais","amount":"1","unit":"l","note":""},{"name":"Damasco","amount":"1","unit":"kg","note":""},{"name":"Canela em Pau","amount":"1","unit":"unidade","note":""},{"name":"Açúcar","amount":"800","unit":"g","note":""},{"name":"Água","amount":"400","unit":"ml","note":""}]', '2000', '["Lave os damascos bem maduros, retire os caroços cozinhe-os em pouca água em fogo baixo por 5 minutos.\nPasse a polpa por uma peneira, esmagando-a com uma colher de pau.","Coloque em uma jarra com álcool e canela, quebre os grãos(sementes do damasco) e adicione.\nDeixe macerar por 30 dias.","Coloque a água e o açúcar em uma panela aqueça em fogo baixo, mexendo sempre, até o açúcar derreter, deixe esfriar.\nAdicione o conteúdo junto ao álcool na jarra ao vinho doce, deixe repousar por 5 dias e filtre finamente. Decantar e engarrafar."]', NULL, '3 a 5 anos', NULL),
(38, 'Licor de Maçã Verde', '[{"name":"Álcool de cereal","amount":"1","unit":"l","note":""},{"name":"Maçã Verde","amount":"2","unit":"kg","note":"Maduras"},{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '1000', '["Descasque e corte as maçãs em quartos retirando as sementes. Coloque-os em uma jarra com o álcool e metade do açúcar. Agite e deixe marinar por 1 mês.","Faça uma calda grossa com o resto do açúcar e a água, adicione ao vidro com a maceração e leve para descansar por mais 15 dias e depois com ajuda de uma peneira pano de algodão ou filtro de papel, filtre a infusão engarrafe e etiquete.","Armazenar em local fresco e escuro, longe de fontes de luz, calor e odores fortes."]', NULL, '3 a 5 anos', NULL),
(39, 'Licor de Hibisco', '[{"name":"Bebida Base","amount":"600","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Hibisco Seco Vermelho","amount":"86","unit":"g","note":"ou 30 colheres de sopa."},{"name":"Açúcar","amount":"500","unit":"g","note":""},{"name":"Água","amount":"500","unit":"ml","note":""}]', '600', '["Umedeça as flores.\nEm um recipiente higienizado coloque as flores e a bebida base e deixe macerar por 30 dias em local fresco e escuro.\nCom ajuda de uma peneira pano de algodão ou filtro de papel filtre a infusão.","CALDA: Leve uma panela ao fogo baixo e coloque a água e o açúcar até derreter e ficar uma calda fina e perolada deixe esfriar e adicione a infusão.\nFeche o recipiente e deixe macera por mais 10 dias. Após filtre com filtro de papel engarrafe e etiquete."]', NULL, '5 anos', NULL),
(40, 'Licor de Flor de Laranjeira', '[{"name":"Bebida Base","amount":"500","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Flores de Laranjeira","amount":"250","unit":"g","note":""},{"name":"Água","amount":"500","unit":"ml","note":""},{"name":"Açúcar","amount":"500","unit":"g","note":""}]', '500', '["Um recipiente limpo. Lave bem as pétalas tire as penugens e o miolo. Coloque no recipiente e coloque a bebida da sua preferência feche envolva em papel alumínio ou plástico e deixe macera por30 dias agite sempre que puder.\nApós 30 dias filtre com ajuda de uma peneira e pano de algodão.","CALDA: Leve uma panela ao fogo médio coloque a água e o açúcar mexa até caramelizar retire e deixe amornar adicione ao licor e deixe descansar por 20 dias após isso filtre novamente engarrafe e etiquete"]', NULL, '3 a 5 anos', NULL),
(41, 'Licor de Flor de Sabugueiro', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Umbelas de Sabugueiro","amount":"200","unit":"g","note":"ou 20 - 30 umbelas"},{"name":"Limão","amount":"1","unit":"unidade","note":"as cascas do limão"},{"name":"Açúcar","amount":"200","unit":"g","note":""},{"name":"Água","amount":"200","unit":"ml","note":""}]', '1000', '["Sacudir gentilmente as flores de forma a eliminar algum inseto indesejado. Cortar os caules, aproveitado apenas as flores viçosas e rejeitando as que se apresentem escuras esterilizar um recipiente de vidro. Introduzir as flores e cobrir com cascas de limão finamente cortadas. Estas evitarão o contato das flores como ar e a sua possível oxidação. Verter o rum até cobrir totalmente as flores e as cascas de limão. Fechar bem o frasco.","Envolve-lo com folha de alumínio e guardar num local escuro e fresco(à temperatura ambiente), durante 30 dias.\nO contato com a luz nesta fase irá provocar o escurecimento das flores e o resultado será um licor acastanhado.\nFindo este período a infusão de flores e rum deve apresentar com um tom amarelo dourado.","CALDA: Leve uma panela ao fogo baixo coloque a água e o açúcar mexa até derrete e ficar uma calda fina deixe esfriar e adicione a infusão.\nCom ajuda de uma peneira pano de algodão filtro de papel engarrafe e etiquete."]', NULL, '5 anos', NULL),
(42, 'Licor de Violeta', '[{"name":"","amount":"","unit":"ml","note":""}]', '500', '[""]', NULL, '2 anos', NULL),
(43, 'Licor de Violeta', '[{"name":"Bebida Base","amount":"500","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Pétalas de Violetas","amount":"25","unit":"g","note":"ou 50 pétalas, as pétalas tem que ser sem talos e partes verde."},{"name":"Açúcar","amount":"200","unit":"g","note":""},{"name":"Essência de Baunilha","amount":"5","unit":"ml","note":""},{"name":"Água","amount":"200","unit":"ml","note":""}]', '500', '["Em um recipiente higienizado coloque as pétalas e a bebida base e deixe macerar por 10 dia em local fresco e sem luz.","CALDA: Leve uma panela ao fogo baixo coloque a água e o açúcar e mexa até ter uma calda fina e perolada e deixe esfriar.\nCom ajuda de um pano de algodão ou filtro de papel filtre a infusão e coloque a calda.","Opcional: (corante alimentício roxo) Engarrafe e etiquete."]', NULL, '2 anos', NULL),
(44, 'Licor de Anis', '[{"name":"Bebida Base","amount":"700","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Anis Estrelados","amount":"10","unit":"g","note":"ou 15 anis"},{"name":"Essência de Baunilha","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Água","amount":"150","unit":"ml","note":""},{"name":"Açúcar","amount":"300","unit":"ml","note":""},{"name":"Corante Alimentaticio","amount":"1","unit":"colher","note":"colher de chá, corante Azul."}]', '700', '["Em um recipiente higienizado coloque o anis uma colher de sopa de baunilha e a bebida base feche o recipiente e deixe macera por 15 dias em local fresco e escuro sempre agite o recipiente quando for possível.\nApós os 15 com ajuda de uma peneira pano de algodão ou filtro de papel, filtre a infusão.","CALDA: Leve uma panela ao fogo baixo coloque 3 ou 4 anis a água e ferva por 5 minutos e coe.\nRetorne ao fogo e adicione o açúcar mexa até perolar, retire e deixe esfriar e misture adicione o corante alimentar mexa bem em garrafa."]', NULL, '3 a 5 anos', NULL),
(45, 'Licor de Canela', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Canela em Pau","amount":"20","unit":"g","note":"ou 10 canelas."},{"name":"Cravos da ìndia","amount":"6","unit":"unidades","note":"opcional"},{"name":"Açúcar","amount":"300","unit":"g","note":""},{"name":"Água","amount":"150","unit":"ml","note":""}]', '1000', '["Em um recipiente limpo coloque a bebida e as canela em pau separe uma para o xarope.\nDeixe macera por 7 dias agitar sempre que puder.\nCom ajuda de uma peneira pano de algodão ou filtro de papel, filtre a infusão.","CALDA: Leve uma panela ao fogo baixo coloque a açúcar a canela em pau e a água mexa assim que ferver retire a canela e continue mexendo até obter uma calda fina e perolada, deixe esfriar e misture ao licor. Engarrafe e etiquete"]', NULL, '3 a 5 anos', NULL),
(46, 'Licor de Gengibre', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Gengibre","amount":"100","unit":"g","note":""},{"name":"Nozes","amount":"5","unit":"unidades","note":""},{"name":"Essência de Baunilha","amount":"5","unit":"ml","note":""},{"name":"Água","amount":"150","unit":"ml","note":""},{"name":"Açúcar","amount":"300","unit":"g","note":""}]', '1000', '["Um recipiente higienizado. Coloque a bebida base adicione a essência de baunilha e as nozes elas suavizam o licor. Limpe e corte em cubos a gengibre e coloque no recipiente deixe curtir por 15 dias fora da luz de vez em quando agite o recipiente.\nApós 15 dias com ajuda de uma peneire e pano de algodão ou filtro de papel para tirar as impurezas.","CALDA: Leve uma panela ao fogo coloque o açúcar a água misture até subir fervura mecha até ficar perolado deixe esfria e misture ao licor e em garrafa."]', NULL, '3 a 5 anos', NULL),
(47, 'Licor de Menta', '[{"name":"Bebida Base","amount":"1","unit":"l","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Hortelã","amount":"50","unit":"g","note":"ou 100 folhas"},{"name":"Açúcar","amount":"750","unit":"g","note":""},{"name":"Água","amount":"750","unit":"ml","note":""},{"name":"Corante Alimentício Verde","amount":"1","unit":"colher","note":"colher de chá"}]', '1000', '["Um recipiente higienizado.\nCorte a folha de hortelã em pedaços adicione a bebida da sua preferência no recipiente feche e deixe curtir por30 dias envolva em papel alumínio para proteger da luz sempre que possível agita.\nApós 30 dais coar e filtrar com uma peneira e algodão.","CALDA: Preparando o xarope leve uma panela ao fogo baixo adicione a água o açúcar e misture até ferver e ficar perolado.\nMisture os ingredientes e mecha bem adicione o corante alimentar verde e engarrafa."]', NULL, '5 anos', NULL),
(48, 'Licor de Amarula', '[{"name":"Bebida Base","amount":"800","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Leite Condensado","amount":"2","unit":"latas","note":""},{"name":"Creme de Leite (com soro)","amount":"2","unit":"latas","note":""},{"name":"Chocolate Branco","amount":"100","unit":"g","note":""},{"name":"Cacau em Pó","amount":"100","unit":"g","note":""},{"name":"Essência de Baunilha","amount":"2","unit":"colheres","note":"colheres de sopa"}]', '800', '["Bata todos os ingredientes no liquidificador por 5 minutos, até se incorporarem os Ingredientes."]', NULL, '90 dias', NULL),
(49, 'Licor de Chocolate', '[{"name":"Bebida Base","amount":"320","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Leite Condensado","amount":"1","unit":"lata","note":""},{"name":"Água","amount":"320","unit":"ml","note":""},{"name":"Açúcar","amount":"150","unit":"g","note":""},{"name":"Chocolate em Pó","amount":"30","unit":"g","note":""},{"name":"Essência de Baunilha","amount":"5","unit":"ml","note":""}]', '320', '["Leve uma panela coloque a água, o açúcar e o chocolate em pó, deixe ferver, depois de fervido deixe esfriar até ficar gelado.\nNo liquidificador coloque a misturada panela fria, coloque o leite condensado, a baunilha e a bebida base bata bastante.\nColoque em um recipiente higienizado e deixe macera por 5 dias na geladeira."]', NULL, '60 dias', NULL),
(50, 'Licor de Doce de Leite', '[{"name":"Bebida Base","amount":"400","unit":"ml","note":"Cachaça, vodka, gin, rum ou álcool cereal"},{"name":"Doce de Leite","amount":"400","unit":"g","note":""},{"name":"Água","amount":"400","unit":"ml","note":""},{"name":"Creme de Leite","amount":"1","unit":"caixa","note":"ou lata"},{"name":"Essência de Baunilha","amount":"5","unit":"ml","note":""}]', '400', '["Em um liquidificador coloque todos os ingredientes e bata por 5 minutos coloque em um recipiente higienizado e deixe macera por 7 dias na geladeira. Engarrafe e etiquete."]', NULL, '180 dias', NULL),
(201, 'Whisky Sour', 'A combinação perfeita de destilado, cítrico e doçura, com uma textura sedosa.', '[{"name":"Bourbon (Whiskey)","measure":"60 ml"},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Xarope Simples","measure":"15 ml"},{"name":"Clara de Ovo","measure":"15 ml (Opcional)"},{"name":"Angostura Aromatic Bitters","measure":"2 dashes"}]', 'Twist de laranja e cereja', 'Batido', 'Internet', NULL),
