(671, 'Bitter Mai Tai', NULL, '[{"name":"Campari","measure":"45 ml"},{"name":"22,5 ml Jamaican Rum","measure":""},{"name":"Licor de Laranja","measure":"15 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"22,5 ml Orgeat","measure":""}]', 'ramo Hortelã', 'Montado', 'Internet', NULL),
(672, 'Piscininha Amor', NULL, '[{"name":"Xarope de Curaçau Blue","measure":"15 ml"},{"name":"Brütt, Espumante","measure":"completar"}]', 'Meia rodela de laranja', 'Montado', 'Internet', NULL),
(674, 'Bombeirinho', 'Mais um ícone dos coquetéis, o bombeirinho surgiu na década de 1980, época em que os ingredientes doces como groselhas, refrigerantes e leite condensado se popularizaram.', '[{"name":"Cachaça","measure":"30 ml"},{"name":"Suco de Limão","measure":"10 ml "},{"name":"Groselha","measure":"10 ml"}]', NULL, 'Mexido', 'Internet', NULL),
(675, 'Corpse Reviver #2', 'É um coquetel seco e cítrico, uma versão super aromática de um White Lady, devido à baixa quantidade de Gim é também um coquetel com menor teor alcoólico e excelente como aperitivo.', '[{"name":"Gin","measure":"30 ml"},{"name":"Lillet Blanc ou Vinho Aperitivo","measure":"30 ml"},{"name":"Cointreau (Triple Sec)","measure":"30 ml "},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Absinto","measure":"5 gotas"}]', 'Casca de limão siciliano', 'Batido', 'Internet', NULL),
(679, 'Vieux Carré', 'O Vieux Carré é um coquetel oficial da IBA feito com uísque de centeio, conhaque, vermute doce, Bénédictine e Peychaud''s bitters. Originou-se com Walter Bergeron, um barman no Carousel Bar no Hotel Monteleone, New Orleans. O nome é francês para “praça velha”, em referência ao bairro French Quarter da cidade.', '[{"name":"Rye Whiskey","measure":"22,5 ml"},{"name":"Conhaque","measure":"22,5 ml"},{"name":"Vermute Rosso (Doce)","measure":"22,5 ml"},{"name":"Licor Bénédictine","measure":"2 colheres de bar"},{"name":"Angostura Aromatic Bitters","measure":"4 dashes"}]', 'Cereja e Casca de limão torcida', 'Mexido', 'Internet', NULL),
(682, 'Blue Blazer (original)', 'O Blue Blazer é um coquetel histórico e teatral criado por Jerry Thomas, caracterizado por ser incendiado e transferido entre duas canecas de metal, criando uma chama azul. Leva uísque escocês, água fervente e açúcar, resultando em um sabor defumado e intenso, servido com casca de limão.', '[{"name":"Whiskey Escocês","measure":"60 ml"},{"name":"Água Quente","measure":"60 ml"},{"name":"Xarope de Açúcar","measure":"10 ml"}]', 'Casca de limão siciliano.', 'Batido', 'Internet', NULL),
(683, 'White Lady', 'Com uma história tenebrosa o White Lady, desta vez o coquetel, foi criado pelo bartender Harry MacElhone em 1919 no Ciro Club de Londres usando partes iguais de licor de menta, triple sec e suco de limão siciliano. Provavelmente esta receita de arrepiar era resquício dos tempos difíceis pós primeira guerra mundial.', '[{"name":"London Dry Gin","measure":"50 ml"},{"name":"Cointreau (Triple Sec)","measure":"25 ml"},{"name":"Suco de Limão Siciliano","measure":"25 ml"},{"name":"Clara de Ovo","measure":"30 ml"}]', NULL, 'Batido', 'Internet', NULL),
(684, 'Tommy''s Margarita', 'A Tommy''s Margarita é uma releitura moderna e oficial da IBA (International Bartenders Association), criada nos anos 90 por Julio Bermejo em San Francisco, Califórnia. Ela se diferencia da clássica por eliminar o licor de laranja, utilizando néctar de agave para destacar o sabor da tequila.', '[{"name":"Tequila Reposado","measure":"60 ml"},{"name":"Suco de Limão Siciliano","measure":"30 ml"},{"name":"Xarope de Agave","measure":"15 ml"}]', 'Rodela ou cunha de limão', 'Batido', 'Internet', NULL),
(685, 'Russian Spring Punch ', 'O Russian Spring Punch mistura vodka espumante e frutas. O termo Russian vem da vodka. O termo Spring Punch vem da mistura de vinho com frutas em jarras para servir muitas pessoas. Foi criando em Londres na década de 1980 pelo bartender Dick Bradsell.', '[{"name":"Vodka","measure":"50 ml"},{"name":"Xarope de Açúcar","measure":"15 ml"},{"name":"Suco de Limão Siciliano","measure":"20 ml"},{"name":"Licor de Framboesa","measure":"15 ml"},{"name":"Licor de Creme de Cassis","measure":"15 ml"},{"name":"Brütt, Espumante","measure":"completar"}]', NULL, 'Batido', 'Internet', NULL),
(686, '#Natal', NULL, '[{"name":"Suco de Limão Siciliano","measure":"10 ml"},{"name":"Licor Curaçau Blue","measure":"50 ml"},{"name":"Energético RB Blueberry e Baunilha","measure":"1 unidade"},{"name":"Sprite","measure":"completar"}]', 'Leite condensado e coco ralado na borda', 'Montado', 'Internet', NULL),
(688, 'Martini Paradise', NULL, '[{"name":"Rum Ouro","measure":"25 ml"},{"name":"Xarope de Grenadine","measure":"25 ml"},{"name":"Suco de Laranja","measure":"50 ml"},{"name":"Suco de Abacaxi","measure":"25 ml"},{"name":"Licor Curaçau Blue","measure":"25 ml"}]', 'Morango e ramo de hortelã', 'Montado', 'Internet', NULL),
(689, 'Mexican Mule', NULL, '[{"name":"Tequila Blanco ou Prata","measure":"60 ml"},{"name":"Suco de Limão","measure":"30 ml"},{"name":"Ginger Beer (ver Cerveja de Gengibre )","measure":"completar"}]', 'Ramo hortelã e cunha limão', 'Montado', '@art.of.cocktails', NULL),
(690, 'Green Phantom', NULL, '[{"name":"Xarope de Curaçau Blue","measure":"15 ml"},{"name":"Xarope de Maracujá","measure":"10 ml"},{"name":"Suco de Limão","measure":"5 ml"},{"name":"Energético Monster Ultra","measure":"completar"},{"name":"Polpa de Maracujá","measure":"1/2 unidade"}]', 'Fatia de limão e maracujá', 'Batido', 'Internet', NULL),
(2, 'Xarope de Açafrão', '[{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Açafrão","amount":"1/4","unit":"colher de sopa","note":""}]', '250', '["Método: Infusão"," Junte todos os ingredientes em uma panela pequena, e coloque em fogo médio, mexendo até que o açúcar se dissolva por completo. Assim que levantar fervura, desligue o fogo e deixe a mistura esfriar. Com um tea strainer, coe com auxílio de um funil para uma garrafa."]', NULL, '1 mês', NULL),
(3, 'Xarope de Abacaxi', '[{"name":"Abacaxi médio","amount":"1","unit":"unidade","note":""},{"name":"Açúcar","amount":"960","unit":"g","note":""},{"name":"Água","amount":"480","unit":"ml","note":""}]', '600', '["Método: Maceração","Em um recipiente adicione a água e o açúcar e mexa até dissolver. Corte o abacaxi em cubos e acrescente à mistura. Deixe tudo descansando por 24 horas. Tire os cubos de abacaxi e reserve-os. Com um espremedor, extraia o suco dos cubos de abacaxi e adicione à mistura. Mexa até dissolver possíveis grãos de açúcar residuais. Com um tea strainer, coe com auxilio de um funil para uma garrafa. Adicione um dash de vodka para conservar. "]', NULL, '30 dias', NULL),
(4, 'Xarope de Acerola', '[{"name":"Acerola","amount":"300","unit":"g","note":""},{"name":"Açúcar","amount":"250","unit":"g","note":""},{"name":"Água","amount":"180","unit":"ml","note":""}]', '200', '["Numa panela colocar a acerola e macerar, em fogo médio, em outra panela acrescentar as acerolas, incorporar o açúcar, mexer um pouco com uma colher de pau, e acrescentar a água.","Agora mexer bem, até o açúcar diluir, e deixar por 10 minutos no fogo. Esperar esfriar e depois coar num recipiente utilizando uma peneira fina e depois num filtro de café."]', NULL, '30 dias', NULL),
(5, 'Xarope de Açúcar Demerara', '[{"name":"Açúcar Demerara","amount":"1","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""}]', '200', '["Em uma panela, adicione parte iguais de água e demerara, em fogo médio, mexendo devagar, até que o açúcar se dissolva por completo, tornando o líquido transparente. Sua tonalidade e textura são semelhantes às do caramelo. Quando levantar fervura, desligue o fogo e deixe a mistura esfriar, coando com uma peneira fina e a ajuda de um funil para uma garrafa. Tampe e guarde na geladeira. Dura até duas semanas. Controle a validade etiquetando seu xarope com a data de produção."]', NULL, '30 dias', NULL),
(6, 'Xarope de Açúcar Mascavo', '[{"name":"Açúcar Mascavo","amount":"1","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""}]', '250', '["Misture o açúcar mascavo e a água e misture numa panela em fogo médio até que o açúcar se dissolva por inteiro, desligue o fogo e deixe esfriar. Coe com auxílio de uma peneira e um funil para uma garrafa e tampe. Guarde sob refrigeração por até duas semanas. Etiquete com a data de produção."]', NULL, '30 dias', NULL),
(7, 'Xarope de Aipo', '[{"name":"Aipo Picado","amount":"240","unit":"g","note":""},{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""}]', '250', '[" Em uma panela, junte todos os ingredientes e leve ao fogo médio, sempre mexendo. Após o ponto de fervura, cozinhe a mistura por 5 minutos. Em seguida, retire do fogo e deixe esfriar. Com um tea strainer e um funil, coe para uma garrafa."]', NULL, '2 semanas', NULL),
(8, 'Xarope de Alfazema', '[{"name":"Alfazema Culinária","amount":"2","unit":"colheres","note":"colheres de sopa"},{"name":"Açúcar","amount":"180","unit":"g","note":""},{"name":"Água","amount":"180","unit":"ml","note":""}]', '200', '["Método: infusão","Junte todos os ingredientes em uma panela e aqueça sob fogo médio, mexendo para dissolver o açúcar até o ponto de fervura. Desligue o fogo e deixe esfriar até a temperatura ambiente. Com um tea strainer e um funil, coe para uma garrafa."]', NULL, '2 semanas', NULL),
(9, 'Xarope de Amora', '[{"name":"Amoras","amount":"250","unit":"g","note":""},{"name":"Pimenta Jamaica","amount":"5","unit":"sementes","note":"sementes trituradas"},{"name":"Laranja","amount":"1","unit":"casca","note":"sem a parte branca"},{"name":"Água","amount":"200","unit":"ml","note":""},{"name":"Açúcar","amount":"200","unit":"g","note":""}]', '200', '["Dar uma leve macerada nas amoras, em fogo médio, colocar primeiro a água depois, a casca de laranja, as sementes Jamaica, as amoras e no final o açúcar. Dê uma quebradinha nas amoras, e incorpore o açúcar.","Mexer até diluir o açúcar, quando começar a fervura colocar o fogo entre o médio e baixo, deixar por 5 a 8 minutos. Esperar esfriar, coar com peneira bem fina e depois colocar na garrafa."]', NULL, '30 dias', NULL),
(10, 'Xarope de Banana', '[{"name":"Banana Prata","amount":"200","unit":"g","note":""},{"name":"Canela","amount":"30","unit":"g","note":""},{"name":"Cravo","amount":"10","unit":"g","note":""},{"name":"Xarope de Açúcar","amount":"650","unit":"ml","note":""},{"name":"Água","amount":"250","unit":"ml","note":""}]', '800', '["Mesma forma de preparo do Xarope de Frutas Vermelhas. Coloque em uma garrafa bem fechada e mantenha-os na geladeira (assim ela durará mais tempo e evitará que chame formiga)."]', NULL, '30 dias', NULL),
(11, 'Xarope de Baunilha', '[{"name":"Açúcar Demerara","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""},{"name":"Extrato de Baunilha","amount":"3","unit":"colgeres","note":"colheres de chá, se for usar essência são 6 colheres de chá"}]', '340', '["Método: Infusão / Maceração","Em uma panela, com fogo médio, adicione o açúcar e a água. Dissolva bem. Depois, vai mexendo sempre. Coloque as colheres de extrato de baunilha e deixe no fogo por 10 minutos. Deixe resfriar e depois envase."]', NULL, '30 dias', NULL),
(12, 'Xarope de Beterraba', '[{"name":"Beterrabas","amount":"6-8","unit":"unidades","note":"beterrabas médias e sem casca"},{"name":"Açúcar","amount":"720","unit":"g","note":""},{"name":"Água","amount":"","unit":" ","note":"para cobrir a mistura"}]', '500', '["Em uma panela, adicione as beterrabas cortadas em cubos e o açúcar. Em seguida, coloque água suficiente para cobrir a mistura. Cozinhe em fogo médio durante 30 minutos ou até que os pedaços estejam ligeiramente macios. Tire do fogo e coe com um tea strainer para uma garrafa."]', NULL, '2 semanas', NULL),
(13, 'Xarope de Caju', '[{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""},{"name":"Suco de Caju","amount":"500","unit":"ml","note":""},{"name":"Chá de Caldo de Limão","amount":"240","unit":"ml","note":"ou 4 colheres de sopa"}]', '1000', '["Espremer os cajus com as mãos limpas; juntar um pouco de caldo de Limão; medir a quantidade de suco obtida; medir uma porção de açúcar correspondente ao dobro do suco de caju obtido;","Fazer uma calda grossa com açúcar e água; adicionar o suco e mexer com uma colher de pau; levar o preparo ao fogo; retirar do fogo logo que levantar fervura; tirar a espuma e deixar repousar um pouco;","Passar o xarope no coador de pano fino; engarrafar ainda quente e arrolhar a garrafa depois de frio."]', NULL, '30 dias', NULL),
(14, 'Xarope de Camomila', '[{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Açúcar Demerara","amount":"240","unit":"g","note":""},{"name":"Chá de Camomila","amount":"4","unit":"colheres","note":"medida são colheres de sopa"}]', '250', '["Método: Infusão","Junte o açúcar e a água em uma panela em fogo alto e misture até que o açúcar se dissolva. Faça a a infusão do chá por 20 minutos e coe com um tea strainer e um funil para uma garrafa. deixe esfriar, tampe e armazene na geladeira."]', NULL, '2 semanas', NULL),
(15, 'Xarope de Canela', '[{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Canela em Pau","amount":"4","unit":"unidades","note":"quebrar em pedaços menores"}]', '250', '["Método: Infusão/decocção","Em uma panela, aqueça todos ingredientes em fogo médio. Chegando ao ponto de fervura, reduza para fogo baixo e mantenha entre 8 e 10 minutos, mexendo constantemente até que o açúcar dissolva por completo. Tire do fogo e coe para uma garrafa, removendo também os pedaços de canela."]', NULL, '2 semanas', NULL),
(16, 'Xarope de Cardamomo', '[{"name":"Açúcar","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Vagens de Cardamomo negro","amount":"6","unit":"vagens","note":"ou substitua por 3 gotas de essência de cardamomo negro"}]', '360', '["Método: Infusão","Junte todos os ingredientes em uma panela em fogo médio e misture até que o açúcar se dissolva. Deixe esfriar e coe com um tea strainer e um funil para uma garrafa."]', NULL, '60 dias', NULL),
(17, 'Xarope de Cereja', '[{"name":"Glicerina","amount":"30","unit":"ml","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Bagaços de Cereja","amount":"30","unit":"ml","note":""},{"name":"Suco de Cereja","amount":"120","unit":"ml","note":"suco fresco"},{"name":"Açúcar","amount":"300","unit":"ml","note":""}]', '300', '["Método: Maceração/Infusão","Misture a glicerina com 120 ml de água e o bagaço de cerejeira e deixe descansar por 24 horas. Coe a mistura para uma garrafa. Agora cubra os mesmos bagaços com 120 ml de água quente e deixe descansar por 1 hora. Coe este líquido para a mesma garrafa do primeiro passo. Adicione o suco de cereja até completar 350 ml de líquido e, em seguida, complete com o açúcar e mexa até ser totalmente dissolvido."]', NULL, '30 dias', NULL),
(18, 'Xarope de Cerveja Pilsen', '[{"name":"Cerveja Pilsen","amount":"500","unit":"ml","note":""},{"name":"Açúcar","amount":"300","unit":"ml","note":""}]', '500', '["Ferver em fogo baixo a cerveja e acrescentar o açúcar. Mexer até dissolver. Deixar ferver por 15 minutos, até atingir o ponto de xarope. Deixar esfriar e passar para um frasco esterilizado."]', NULL, '20 dias', NULL),
(19, 'XAROPE DE CEVADA', '[{"name":"Açúcar","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Cevada Torrada e Moída","amount":"1","unit":"colheres","note":"colheres de sopa cheias"}]', '350', '["Método: infusão","Em uma panela, junte a cevada e a água e aqueça em fogo médio, até atingir o ponto de fervura. Tire do fogo e passe a mistura por um filtro de papel. Retorne o líquido para a panela e acrescente o açúcar, mexendo até dissolvê-lo por completo. Desligue o fogo e deixe esfriar. Coe para uma garrafa e armazene na geladeira."]', NULL, '2 semanas', NULL),
(20, 'Xarope de Chocolate', '[{"name":"Cacau em Pó","amount":"30","unit":"g","note":"sem açúcar o cacau"},{"name":"Açúcar","amount":"3","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Extrato de Baunilha","amount":"3/4","unit":"colher","note":"colher de sopa como medida"},{"name":"Óleo de Canela","amount":"1","unit":"gota","note":"opcional"}]', '350', '["Método: decocção","Em uma panela, junte o cacau em pó, o açúcar e a água e coloque no fogo médio, sempre misturando. Após levantar fervura, misture por mais três minutos. Desligue e deixe esfriar. Adicione o extrato de baunilha e o óleo de canela. Misture e engarrafe sem coar. Tampe e guarde na geladeira."]', NULL, '30 dias', NULL),
(21, 'Xarope de Cravo da Índia', '[{"name":"Açúcar Demerara","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Cravos da Índia","amount":"1/3","unit":"xícara","note":""}]', '240', '["Método: Infusão","Em uma panela, junte todos os ingredientes e aqueça em fogo médio, sempre mexendo. Pouco antes do ponto de fervura, reduza para o fogo baixo e deixe cozinhando por 20 minutos, mexendo de vez em quando. Desligue o fogo e deixe esfriar. Em seguida, coe com o tea strainer e um funil para uma garrafa. Tampe e armazene sob refrigeração."]', NULL, '2 semanas', NULL),
(22, 'Xarope de 5 Especiarias', '[{"name":"Açúcar","amount":"1/2","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""},{"name":"Mel","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Anis Estrelado","amount":"2","unit":"colheres","note":"colher de sopa"},{"name":"Semente de Funcho","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Pimenta-de-Sichuan","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Cravos da Índia","amount":"1/2","unit":"colher","note":"colher de sopa"},{"name":"Canela em Pau","amount":"1","unit":"unidade","note":"quebrada em pedaços pequenos"}]', '250', '["Adicione as especiarias em uma panela em fogo médio até que liberem os aromas, em cerca de 3 ou 4 minutos. Adicione, em seguida, o restante dos ingredientes. Após o ponto de fervura, cozinhe por 5 minutos. Desligue o fogo e deixe esfriar. Coe para uma garrafa, tampe e guarde na geladeira."]', NULL, '2 semanas', NULL);